// French for the main pages' French twins (/fr, /fr/food-drink, /fr/kelowna ...), in Canadian French. Used by
// frenchTwinHtml() in server.js. FR_TEXT holds whole pieces of visible text (also attribute values and string literals
// in page scripts) keyed by their English; numbers in a piece are matched as {0}, {1} ..., and links or bold text
// inside a sentence as {a0}, {a1} ... (so the French can reorder them). FR_PATTERNS handle text built from parts
// (opening times, "Kelowna · Italian · 4.6★", "Add X to trip"). FR_SCRIPT are exact fragments of page-script source.
// Place names and town names are never translated. app.js's own French is used for anything not listed here.

const MONTHS = { Jan: 'janv.', Feb: 'févr.', Mar: 'mars', Apr: 'avr.', May: 'mai', Jun: 'juin', Jul: 'juill.', Aug: 'août', Sep: 'sept.', Oct: 'oct.', Nov: 'nov.', Dec: 'déc.' };
