const DAYS_LONG = { Monday: 'lundi', Tuesday: 'mardi', Wednesday: 'mercredi', Thursday: 'jeudi', Friday: 'vendredi', Saturday: 'samedi', Sunday: 'dimanche' };
// "5 PM" -> "17 h", "8:30 PM" -> "20 h 30", "12 AM" -> "minuit".
function frTime(h, mm, ap) {
  let n = Number(h) % 12;
  if (String(ap).toUpperCase() === 'PM') n += 12;
  if (n === 0 && !mm) return 'minuit';
  return `${n} h${mm && mm !== '00' ? ` ${mm}` : ''}`;
}
const TIME = '(\\d{1,2})(?::(\\d\\d))? ?(AM|PM|am|pm)';

